import useAxios from '../../hook/useAxios/useAxios'

import './Today.css'

function Today ({city}) {
    const {data} = useAxios({city: city})

    return(
        <div>
            <p>{data?.name}</p>
            <p>{data?.main.temp}</p>
            <p>{data?.weather[0].main}</p>

        </div>
    )
}

export default Today
